[Form]
public class METVendorRebateJournalInquiry extends FormRun
{
    QueryBuildRange qbdrJournalName;
    LedgerJournalEngine ledgerJournalEngine;


}

/// <summary>
/// Calculate charges for product receipt
/// </summary>
private void calcChargesForProductReceipt()
{
    PurchTable           PurchTable;        
    VendPackingSlipTrans vendPackingSlipTransLoc;
    VendPackingSlipJour  vendPackingSlipJourLoc;
    PurchAutomaticPurchaseDocumentLineChargeV2Entity purchChargeEntity;
    METPurchGroup purchGroup;

    VendPackingSlipTrans vendpackingSlipTransBuf = VendPackingSlipTrans_ds.cursor();
    LedgerJournalTable ledgerJournalTableLoc = LedgerJournalTable_ds.cursor();

    delete_from metVendorRebateOffRemittanceChargesCalcTmp;

    insert_recordset metVendorRebateOffRemittanceChargesCalcTmp
            ( PackingSlipTransRecId, LineAmount, ChargeCode, ChargePercent, PurchGroupId)
        select RecId, ValueMST from vendPackingSlipTransLoc
            where vendPackingSlipTransLoc.RecId == vendpackingSlipTransBuf.RecId
        join vendPackingSlipJourLoc
            where vendPackingSlipJourLoc.RecId == vendPackingSlipTransLoc.VendPackingSlipJour
        join PurchTable
            where PurchTable.PurchId == vendPackingSlipJourLoc.PurchId
        join PurchaseChargeCode, ChargePercentage, METPurchGroupId from purchChargeEntity
            where purchChargeEntity.ChargingVendorAccountNumber == PurchTable.InvoiceAccount
                && purchChargeEntity.METFromDate <= DateTimeUtil::date(ledgerJournalTableLoc.PostedDateTime)
                && purchChargeEntity.METToDate >=  DateTimeUtil::date(ledgerJournalTableLoc.PostedDateTime)
        exists join purchGroup
            where purchGroup.PurchGroupId == purchChargeEntity.METPurchGroupId
            && purchGroup.InvoiceType == METPurchGroupInvoiceType::Warehouse;

    update_recordset metVendorRebateOffRemittanceChargesCalcTmp
        setting ChargeAmount = metVendorRebateOffRemittanceChargesCalcTmp.LineAmount * (metVendorRebateOffRemittanceChargesCalcTmp.ChargePercent/100)
        where metVendorRebateOffRemittanceChargesCalcTmp.PackingSlipTransRecId ==  vendpackingSlipTransBuf.RecId;


    METVendorRebateOffRemittanceChargesCalcTmp_DS.research(true);
    METVendorRebateOffRemittanceChargesCalcTmp_DS.executeQuery();

}

/// <summary>
/// Initializes the form components and data sources.
/// </summary>
public void init()
{
    super();
    ledgerJournalEngine = LedgerJournalEngine::construct(LedgerJournalType::Daily, element);
    ledgerJournalEngine.ledgerJournalTable(element.args().record());

    qbdrJournalName = LedgerJournalTable_ds.queryBuildDataSource().addRange(fieldNum(LedgerJournalTable, JournalName));
    qbdrJournalName.value(METVendParameters::find().RebateAccrualJournalName);
}

/// <summary>
/// Relcalculate charges on selection changed
/// </summary>
public void selectionChanged()
{
    super();

    element.calcChargesForProductReceipt();
}

/// <summary>
/// Add range on performing execute query
/// </summary>
public void executeQuery()
{
    this.queryBuildDataSource().clearRanges();

    this.queryBuildDataSource().addRange(fieldNum(METVendorRebateOffRemittanceChargesCalcTmp, PackingSlipTransRecId))
        .value(SysQuery::value(VendPackingSlipTrans_ds.cursor().RecId));

    super();
}
